builder.Services.AddOptions<PaymentGatewayOptions>()
    .BindConfiguration("PaymentGateway")
    .ValidateDataAnnotations()
    .Validate(o => !o.BaseUrl.StartsWith("http:"), "TLS required")
    .ValidateOnStart();
